import { uv, vec2, vec3, smoothstep, float, uniform, mix, Fn, mul, sub, abs, add, pow } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  const spec = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const ink = spec.ink ?? '#16161d';
  const paper = spec.paper ?? '#e8ecf2';
  const accent = spec.accent ?? '#ff2a38';
  const surface = spec.surface ?? '#0b0b10';

  const group = new Group();
  group.name = config.id ?? 'hub-collection-badge';

