  const geom = new PlaneGeometry(1.0, 0.42, 1, 1);

  // uniforms
  const uHover = uniform(float(0));
  const uPress = uniform(float(0));
  const uAccent = uniform(vec3(new Color(accent)));
  const uInk = uniform(vec3(new Color(ink)));
  const uSurface = uniform(vec3(new Color(surface)));
  const uPaper = uniform(vec3(new Color(paper)));

  // capsule SDF: center at 0, rect 1.0 x 0.42, radius ~0.21 (full capsule)
  const capsuleSDF = Fn(([uvCoord]) => {
    const p = uvCoord.mul(2).sub(1); // -1..1
    const half = vec2(0.5, 0.21);
    const q = abs(p).sub(half);
    const qx = q.x.max(0);
    const qy = q.y.max(0);
    const outer = mul(qx.mul(qx).add(qy.mul(qy)), 0.5);
    // round: distance to rounded edge
    const r = float(0.21);
    const d = outer.sub(r).max(q.x.max(q.y));
    return d;
  });

  // edge-band SDF: thin ring near border
  const edgeSDF = Fn(([uvCoord]) => {
    const p = uvCoord.mul(2).sub(1);
    const half = vec2(0.5, 0.21);
    const q = abs(p).sub(half);
    const qx = q.x.max(0);
    const qy = q.y.max(0);
    const outer = mul(qx.mul(qx).add(qy.mul(qy)), 0.5);
    const r = float(0.21);
    const dOuter = outer.sub(r).max(q.x.max(q.y));
    const dInner = outer.sub(r.sub(0.03)).max(q.x.max(q.y));
    return dInner.negate().max(dOuter);
  });

  const mat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  mat.toneMapped = true;

  mat.colorNode = Fn(() => {
    const caps = capsuleSDF(uv);
    const edge = edgeSDF(uv);

    const mask = smoothstep(float(0.02), float(0.0), caps); // 1 inside, 0 outside
    const edgeMask = smoothstep(float(0.04), float(0.0), edge); // thin ring
    const edgeGlow = smoothstep(float(0.12), float(0.0), edge).pow(2); // glow spread

    // base fill: ink panel with subtle surface gradient
    const g = uv.y; // vertical
    const baseGrad = mix(uSurface, uInk, g.mul(0.6).add(0.2));
    const base = mix(baseGrad, uPaper.mul(0.1), uHover);

    // accent edge: bright on hover/focus, dim idle
    const edgeIntensity = uHover.mul(0.8).add(0.25);
    const accentEdge = uAccent.mul(edgeIntensity);
    const glow = uAccent.mul(edgeGlow.mul(0.35));
    const edgeColor = accentEdge.add(glow);

    // press darken
    const finalColor = mix(base, edgeColor, edgeMask.mul(0.9));
    const pressed = finalColor.mul(float(1).sub(uPress.mul(0.3)));
    const out = pressed.mul(mask).add(vec3(0).mul(float(1).sub(mask)));

    return vec4(out, mask);
  })();

  mat.opacityNode = Fn(() => {
    const caps = capsuleSDF(uv);
    const mask = smoothstep(float(0.02), float(0.0), caps);
    return mask;
  })();

