    const mask = smoothstep(float(0.08), float(0.0), caps);
    return vec4(uAccent.mul(uHover.mul(0.6).add(0.15)), mask.mul(uHover.mul(0.5).add(0.3)));
  })();
  const backMesh = new Mesh(backGeom, backMat);
  backMesh.position.z = -0.03;
  group.add(backMesh);

