    // blend grain into color via a separate overlay node? Keep simple: assign to map won't work with TSL colorNode.
    // Store as userData and use in a second overlay plane
    const grainGeom = new PlaneGeometry(1.0, 0.42, 1, 1);
    const grainMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
    grainMat.colorNode = Fn(() => {
      const caps = capsuleSDF(uv);
      const mask = smoothstep(float(0.02), float(0.0), caps);
      const grain = tex uv(); // not directly — need texture node
      return vec4(vec3(float(0.5)), mask.mul(0.06));
    })();
  }).catch(() => {});

