  group.position.y = 1.6;

  // animation
  const tl = gsap.timeline({ paused: false });
  tl.from(group.position, { y: group.position.y + 0.25, duration: 0.7, ease: 'power3.out' });
  tl.from(group.scale, { x: 0.92, y: 0.92, z: 0.92, duration: 0.9, ease: 'power4.out' }, 0);
  tl.to(group.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.5, ease: 'power3.inOut' }, 0.7);
  tl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 1.2);

  // handlers
  const state = { hovering: false, pressing: false };
  const handlers = {
    onpointerenter: () => {
      state.hovering = true;
      gsap.to(uHover, { value: 1, duration: 0.3, ease: 'power2.out' });
      gsap.to(group.position, { y: group.position.y + 0.15, duration: 0.5, ease: 'power3.out' });
    },
    onpointerleave: () => {
      state.hovering = false;
      gsap.to(uHover, { value: 0, duration: 0.4, ease: 'power2.out' });
      gsap.to(group.position, { y: group.position.y - (state.pressing ? 0 : 0.15), duration: 0.5, ease: 'power3.out' });
    },
    onpointerdown: () => {
      state.pressing = true;
      uPress.value = 1;
      gsap.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' });
    },
    onpointerup: () => {
      state.pressing = false;
      uPress.value = 0;
      gsap.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.5, ease: 'power4.out' });
      ctx.emit('hub-collection.select', { id: 'hub-collection-badge' });
    },
    onpointercancel: () => {
      state.pressing = false;
      uPress.value = 0;
      gsap.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.5, ease: 'power4.out' });
    },
  };
  group.userData.handlers = handlers;
  group.userData.handlers.onhover = handlers.onpointerenter;
  group.userData.handlers.onunhover = handlers.onpointerleave;
  group.userData.handlers.onpress = handlers.onpointerdown;
  group.userData.handlers.onrelease = handlers.onpointerup;
  group.userData.handlers.onclick = handlers.onpointerup;

  group.traverse((o) => {
    if (o.isMesh) {
      o.userData.handlers = handlers;
      o.userData.pointerEnabled = true;
    }
  });

  group.userData.cleanup = () => {
    tl.kill();
    gsap.killTweensOf(uHover);
    gsap.killTweensOf(uPress);
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    geom.dispose();
    backGeom.dispose();
    mat.dispose();
    backMat.dispose();
  };

  return group;
}
